		value, err := jsonArrayText(values.Elements[index])
		if err != "" {
			return nil, err
		}
		pair := SqlJsonPair{Key: *key, Value: SqlJsonNode{Kind: "null", Raw: "null"}}
		if value != nil {
			pair.Value = SqlJsonNode{Kind: "string", String: *value}
		}
