func intervalInput(value string) SqlInterval {
	if special := temporalSpecial(value); special == 1 {
		return SqlInterval{Month: math.MaxInt32, Day: math.MaxInt32, Time: math.MaxInt64, Valid: true}
	} else if special == -1 {
		return SqlInterval{Month: math.MinInt32, Day: math.MinInt32, Time: math.MinInt64, Valid: true}
	}
	text := strings.TrimSpace(value)
	if text == "" {
		return SqlInterval{Error: "22007"}
	}
	ago := false
	if strings.HasSuffix(strings.ToLower(text), " ago") {
		ago = true
		text = strings.TrimSpace(text[:len(text)-4])
	}
	var month int32
	var day int32
	var time int64
	if matched, _ := strconv.Atoi(text); text != "" && func() bool {
		_, err := strconv.Atoi(text)
		return err == nil
	}() {
		time = int64(matched) * 1000000
	} else {
		tokens := strings.Fields(text)
		units := map[string]string{"year": "month", "years": "month", "yr": "month", "yrs": "month", "month": "month", "months": "month", "mon": "month", "mons": "month", "week": "week", "weeks": "week", "day": "day", "days": "day", "hour": "time", "hours": "time", "hr": "time", "hrs": "time", "minute": "time", "minutes": "time", "min": "time", "mins": "time", "second": "time", "seconds": "time", "sec": "time", "secs": "time"}
		scale := map[string]int64{"year": 12, "years": 12, "yr": 12, "yrs": 12, "month": 1, "months": 1, "mon": 1, "mons": 1, "week": 7, "weeks": 7, "day": 1, "days": 1, "hour": 3600000000, "hours": 3600000000, "hr": 3600000000, "hrs": 3600000000, "minute": 60000000, "minutes": 60000000, "min": 60000000, "mins": 60000000, "second": 1000000, "seconds": 1000000, "sec": 1000000, "secs": 1000000}
		for index := 0; index < len(tokens); {
			token := tokens[index]
			sign := int64(1)
			clock := token
			if len(token) > 1 && (token[0] == '+' || token[0] == '-') && strings.Contains(token[1:], ":") {
				if token[0] == '-' {
					sign = -1
				}
				clock = token[1:]
			}
			if strings.Count(clock, ":") >= 1 {
				_, usec, err := temporalParseTime(clock, false)
				if err != "" {
					return SqlInterval{Error: err}
				}
				time += sign * usec
				index++
				continue
			}
			amount, amountErr := strconv.ParseInt(token, 10, 64)
			if amountErr != nil || index+1 >= len(tokens) {
				return SqlInterval{Error: "22007"}
			}
			unit := strings.ToLower(tokens[index+1])
			kind, ok := units[unit]
			factor, factorOk := scale[unit]
			if !ok || !factorOk {
				return SqlInterval{Error: "22007"}
			}
			if kind == "month" {
				month += int32(amount * factor)
			} else if kind == "day" || kind == "week" {
				day += int32(amount * factor)
			} else {
				time += amount * factor
			}
			index += 2
		}
	}
	if ago {
		month = -month
		day = -day
		time = -time
	}
	return SqlInterval{Month: month, Day: day, Time: time, Valid: true}
}
