func temporalOverlaps(nulls [4]bool, cmp func(i, j int) int) SqlBoolean {
	ts1, te1, ts2, te2 := 0, 1, 2, 3
	ts1Null, te1Null, ts2Null, te2Null := nulls[0], nulls[1], nulls[2], nulls[3]
	if ts1Null {
		if te1Null {
			return SqlBoolean{}
		}
		ts1 = te1
		te1Null = true
	} else if !te1Null && cmp(ts1, te1) > 0 {
		ts1, te1 = te1, ts1
	}
	if ts2Null {
		if te2Null {
			return SqlBoolean{}
		}
		ts2 = te2
		te2Null = true
	} else if !te2Null && cmp(ts2, te2) > 0 {
		ts2, te2 = te2, ts2
	}
	order := cmp(ts1, ts2)
	if order > 0 {
		if te2Null {
			return SqlBoolean{}
		}
		if cmp(ts1, te2) < 0 {
			return SqlBoolean{Value: true, Valid: true}
		}
		if te1Null {
			return SqlBoolean{}
		}
		return SqlBoolean{Value: false, Valid: true}
	}
	if order < 0 {
		if te1Null {
			return SqlBoolean{}
		}
		if cmp(ts2, te1) < 0 {
			return SqlBoolean{Value: true, Valid: true}
		}
		if te2Null {
			return SqlBoolean{}
		}
		return SqlBoolean{Value: false, Valid: true}
	}
	if te1Null || te2Null {
		return SqlBoolean{}
	}
	return SqlBoolean{Value: true, Valid: true}
}
func temporalUsecOrder(left, right int64) int {
	if left > right {
		return 1
	}
	if left < right {
		return -1
	}
	return 0
}
