func temporalTimetzOrder(left, right SqlTimeTz) int {
	leftGmt := left.Usec + int64(left.Zone)*1000000
	rightGmt := right.Usec + int64(right.Zone)*1000000
	switch {
	case leftGmt > rightGmt:
		return 1
	case leftGmt < rightGmt:
		return -1
	case left.Zone > right.Zone:
		return 1
	case left.Zone < right.Zone:
		return -1
	default:
		return 0
	}
}
