func timestampFormat(usec int64) string {
	if usec == math.MinInt64 {
		return "-infinity"
	}
	if usec == math.MaxInt64 {
		return "infinity"
	}
	days := usec / 86400000000
	time := usec % 86400000000
	if time < 0 {
		time += 86400000000
		days--
	}
	year, month, day := temporalJ2date(int(days) + 2451545)
	display := year
	if year <= 0 {
		display = -(year - 1)
	}
	text := temporalPad(display, 4) + "-" + temporalPad(month, 2) + "-" + temporalPad(day, 2) + " " + timeFormat(time)
	if year <= 0 {
		text += " BC"
	}
	return text
}
