func temporalFormatZone(west int32) string {
	sign := "+"
	sec := int(west)
	if sec > 0 {
		sign = "-"
	} else {
		sec = -sec
	}
	min := sec / 60
	sec -= min * 60
	hour := min / 60
	min -= hour * 60
	if sec != 0 {
		return sign + temporalPad(hour, 2) + ":" + temporalPad(min, 2) + ":" + temporalPad(sec, 2)
	}
	if min != 0 {
		return sign + temporalPad(hour, 2) + ":" + temporalPad(min, 2)
	}
	return sign + temporalPad(hour, 2)
}
